BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-5125'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='2T0797' OR source_url ~ '[?&]id=5125(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='d9000797-bb50-4371-ab7a-519316005125' OR slug='sam-ngamwongwan-26-land-buildings-2t0797' OR (abs(latitude-13.851588)<0.0001 AND abs(longitude-100.545763)<0.0001 AND abs(land_area_sqm-8692)<1)) THEN RAISE NOTICE 'SAM 2T0797 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('d9000797-bb50-4371-ab7a-519316005125', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'business', 'sale', 'whole_property', 'ที่ดินพร้อมกลุ่มอาคาร 5 ไร่ 1 งาน 73 ตร.ว. งามวงศ์วาน 26 หลักสี่', 'รายละเอียดทรัพย์

ที่ดินพร้อมกลุ่มอาคารและสิ่งปลูกสร้าง ซอยงามวงศ์วาน 26 แยก 3-4 แขวงทุ่งสองห้อง เขตหลักสี่ กรุงเทพมหานคร โฉนดเลขที่ 3369 จำนวน 1 ฉบับ เนื้อที่ 5 ไร่ 1 งาน 73 ตร.ว. หรือ 2,173 ตร.ว. (8,692 ตร.ม.) ราคาประกาศขายทั้งทรัพย์ 121,474,000 บาท รหัส SAM 2T0797 ต้นทางจัดเป็นอสังหาริมทรัพย์อื่นๆ ในเว็บนี้จัดเป็นที่ดินพร้อมสิ่งปลูกสร้าง

แปลงรูปคล้ายสี่เหลี่ยมผืนผ้า ด้านเหนือกว้างประมาณ 86 เมตร โดยส่วนติดถนนกว้างประมาณ 59 เมตร ลึกสุดประมาณ 124 เมตร ด้านใต้ติดคลองบางเขนประมาณ 72 เมตร มีสาธารณูปโภคผ่านหน้าทรัพย์ตาม SAM

สิ่งปลูกสร้างตามทะเบียนรับโอน

SAM ระบุสิ่งปลูกสร้าง 13 รายการ ได้แก่ อาคารพักอาศัย 4.5 ชั้น 1 หลัง อาคารพักอาศัย 3 ชั้น 2 หลัง อาคารพักอาศัย 2.5 ชั้น 3 หลัง บ้านพักคนงานชั้นเดียว 1 หลัง บ้านพักคนงาน 2 ชั้น 1 หลัง อาคารชั้นเดียว (หอพระ) 1 หลัง อาคารแปดเหลี่ยม 3 ชั้น 1 หลัง อาคาร 2 ชั้นพร้อมที่จอดรถ 1 หลัง ศาลาพักผ่อนรูปโดม 1 รายการ และอาคารรูปทรงกลม 5 ชั้น 1 หลัง

จำนวน 13 รายการรวมศาลาและอาคารหลายรูปแบบ ไม่ใช่จำนวนห้องนอน ต้นทางไม่ระบุพื้นที่ใช้สอยรวม จำนวนห้องนอน ห้องน้ำ รายได้หรือสถานะผู้ใช้ประโยชน์ปัจจุบัน ควรตรวจโครงสร้าง ระบบอาคาร สภาพภายในและรายการที่จะโอนจริงก่อนเสนอซื้อ

ทางเข้าและข้อควรทราบ

ซอยงามวงศ์วาน 26 แยก 3-4 หน้าทรัพย์เป็นทางส่วนบุคคล SAM ระบุว่าเปิดให้ใช้เข้าออกโดยเปิดเผยและกรุงเทพมหานครดูแลปรับปรุง ผิวลาดยางกว้างประมาณ 5 เมตร เขตทางประมาณ 6 เมตร ข้อมูลการเปิดใช้และการดูแลไม่ใช่การยืนยันว่าเป็นทางสาธารณะหรือมีสิทธิใช้ทางจดทะเบียน ผู้สนใจต้องตรวจเจ้าของทาง ภาระจำยอมและสิทธิใช้ทางก่อนเสนอซื้อ

ที่ตั้งหน้าโฉนดระบุตำบลทุ่งสองห้อง อำเภอดอนเมือง กรุงเทพมหานคร ขณะที่ส่วนสรุปประกาศระบุแขวงทุ่งสองห้อง เขตหลักสี่ ควรตรวจเอกสารกับข้อมูลเขตปกครองปัจจุบัน SAM ระบุสีผังเมืองเป็นสีแดง ควรตรวจผังเมือง ข้อกำหนดการใช้ประโยชน์และแนวเขต/ระยะร่นริมคลองสำหรับกิจกรรมที่ต้องการ ไม่ถือว่าการมีอาคารเดิมเป็นการยืนยันสิทธิดัดแปลงหรือก่อสร้างเพิ่มเติม

ทำเลและการเดินทาง

ย่านที่อยู่อาศัย ใกล้เดอะมอลล์งามวงศ์วาน โรงพยาบาลนนทเวช และบริเวณพงษ์เพชร–ประชาชื่น ตามข้อมูลต้นทาง จากถนนงามวงศ์วานมุ่งหน้าแคราย เลี้ยวซ้ายที่แยกพงษ์เพชรเข้าประชาชื่นประมาณ 420 เมตร เลี้ยวซ้ายข้ามคลองประปา เข้าถนนเทศบาลรังสรรค์เหนือประมาณ 170 เมตร แล้วเข้าซอยงามวงศ์วาน 26 แยก 3 และแยก 3-4 รวมประมาณ 255 เมตร ถึงทรัพย์

ภาพและการติดต่อ

ภาพจริงและผังจาก SAM คัดไม่ซ้ำ 20 ภาพ ภาพอาคารและภายในส่วนใหญ่ลงวันที่ 10 เมษายน 2567 มีภาพถนนโดยรอบและผังต้นทางประกอบ ภาพไม่ใช่การยืนยันสภาพปัจจุบันหรือรวมทรัพย์ข้างเคียงไว้ในการขาย

พิกัด 13.851588, 100.545763 ดึงจากลิงก์นำทาง SAM และตรงกับแผนที่ เป็นจุดอ้างอิง ไม่ใช่แนวเขตรังวัด ตรวจราคาและสถานะซื้อตรงวันที่ 15 กันยายน 2569 ติดต่อ SAM โทร.02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 2T0797 เพื่อยืนยันเอกสาร ราคา สิทธิใช้ทางและเงื่อนไขล่าสุด', 121474000, false, 8692, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'ซอยงามวงศ์วาน 26 แยก 3-4', 'ด้านใต้ติดคลองบางเขน', 'ถนนงามวงศ์วาน', 13.851588, 100.545763, 'กรุงเทพมหานคร', 'หลักสี่', 'ทุ่งสองห้อง', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-ngamwongwan-26-land-buildings-2t0797') RETURNING id INTO property_listing_id;
