INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=5125&keyref=', '2T0797', now(), 'Checked2026-09-15. THB121474000,8692sqm,Chanote3369,13registered structures including pavilion. Private road5m/ROW6m openly used and BMA maintained per SAM; legal access not certified. Title Don Mueang versus summary Lak Si disclosed. Southern canal72m.20unique source images/plans, main photos2024-04-10. Navigation/map agree. All-status source/code/page/deed/nearby duplicate query empty.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Land and Buildings on Ngam Wong Wan 26, Lak Si, Bangkok', 'Land with multiple buildings at Soi Ngam Wong Wan 26, Yaek 3-4, Thung Song Hong, Lak Si, Bangkok. One Chanote title 3369. Total 5 rai 1 ngan 73 sq.wah, or 2,173 sq.wah (8,692 sq.m.). SAM whole-property asking price THB 121,474,000, reference 2T0797. Source category is other real estate; listed here as land with existing structures.

Approximately rectangular plot: 86 m northern width, including 59 m road frontage; maximum depth 124 m; approximately 72 m southern boundary along Khlong Bang Khen. Source reports utilities passing the frontage.

Registered acquisition inventory has 13 entries: one 4.5-storey residential building, two 3-storey residential buildings, three 2.5-storey residential buildings, one single-storey workers house, one 2-storey workers house, one single-storey shrine building, one 3-storey octagonal building, one 2-storey building with parking, one domed pavilion and one 5-storey circular building. The count includes a pavilion and is not a bedroom count. Total usable area, bedrooms, bathrooms, income and current occupancy are not specified. Inspect structures, systems, condition and actual transfer inventory.

Material access disclosure: frontage Soi Ngam Wong Wan 26 Yaek 3-4 is a private road. SAM says it is openly used for access and maintained by Bangkok Metropolitan Administration, with approximately 5 m paved carriageway and 6 m right of way. This does not establish public-road status or registered access rights. Verify road ownership, easements and legal access before purchase.

Title address states Thung Song Hong, Don Mueang, whereas the source summary uses Lak Si; verify current administrative records. SAM lists red zoning. Confirm current planning, proposed use and canal boundary/setback requirements. Existing buildings do not establish permission for alteration or further construction.

Residential surroundings near The Mall Ngamwongwan, Nonthavej Hospital and Phong Phet/Pracha Chuen. Source route runs via Pracha Chuen, across the waterworks canal, Thetsaban Rangsan Nuea and Soi Ngam Wong Wan 26 Yaek 3 and 3-4.

Twenty unique authentic source photos/plans. Most building/interior photos show 10 April 2024; road context and source plans are also included. Inspect current condition. Navigation/map agree at 13.851588, 100.545763, a reference point rather than surveyed boundary. Direct-sale price/status checked 15 September 2026. Contact SAM 02-686-1888, sales@sam.or.th or LINE @samline quoting 2T0797.', 'Soi Ngam Wong Wan26 Yaek3-4', 'Southern boundary along Khlong Bang Khen', 'Ngam Wong Wan Road', 'Thung Song Hong', 'Lak Si', 'Bangkok', 'Land and Buildings on Ngam Wong Wan 26, Lak Si, Bangkok', 'Land8692sqm with13registered structure entries,THB121474000. Private road access and title address difference disclosed.', 'published', 'ai_assisted', now(), 'land and buildings on ngam wong wan 26, lak si, bangkok land with multiple buildings at soi ngam wong wan 26, yaek 3-4, thung song hong, lak si, bangkok. one chanote title 3369. total 5 rai 1 ngan 73 sq.wah, or 2,173 sq.wah (8,692 sq.m.). sam whole-property asking price thb 121,474,000, reference 2t0797. source category is other real estate; listed here as land with existing structures.

approximately rectangular plot: 86 m northern width, including 59 m road frontage; maximum depth 124 m; approximately 72 m southern boundary along khlong bang khen. source reports utilities passing the frontage.

registered acquisition inventory has 13 entries: one 4.5-storey residential building, two 3-storey residential buildings, three 2.5-storey residential buildings, one single-storey workers house, one 2-storey workers house, one single-storey shrine building, one 3-storey octagonal building, one 2-storey building with parking, one domed pavilion and one 5-storey circular building. the count includes a pavilion and is not a bedroom count. total usable area, bedrooms, bathrooms, income and current occupancy are not specified. inspect structures, systems, condition and actual transfer inventory.

material access disclosure: frontage soi ngam wong wan 26 yaek 3-4 is a private road. sam says it is openly used for access and maintained by bangkok metropolitan administration, with approximately 5 m paved carriageway and 6 m right of way. this does not establish public-road status or registered access rights. verify road ownership, easements and legal access before purchase.

title address states thung song hong, don mueang, whereas the source summary uses lak si; verify current administrative records. sam lists red zoning. confirm current planning, proposed use and canal boundary/setback requirements. existing buildings do not establish permission for alteration or further construction.

residential surroundings near the mall ngamwongwan, nonthavej hospital and phong phet/pracha chuen. source route runs via pracha chuen, across the waterworks canal, thetsaban rangsan nuea and soi ngam wong wan 26 yaek 3 and 3-4.

twenty unique authentic source photos/plans. most building/interior photos show 10 april 2024; road context and source plans are also included. inspect current condition. navigation/map agree at 13.851588, 100.545763, a reference point rather than surveyed boundary. direct-sale price/status checked 15 september 2026. contact sam 02-686-1888, sales@sam.or.th or line @samline quoting 2t0797.') ;
